  base: "./",
  worker: {
    format: "es",
  },
  build: {
    target: "es2020",
    chunkSizeWarningLimit: 4096,
  },
});

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

export type Lang = "en" | "bn";

export type Tender = {
  tender_id: string;
  title: string;
  procuring_entity: string;
  bidder: string;
  submission_deadline: string;
};

export type Requirement = {
  id: string;
  order: number;
  title_en: string;
  title_bn: string;
  mandatory: boolean;
  has_expiry: boolean;
};

export type RequirementsFile = {
  tender: Tender;
  requirements: Requirement[];
};

export type UploadState = "reading" | "ready" | "error";

export type UploadedDocument = {
  id: string;
  file: File;
  name: string;
  size: number;
  pages: number;
  hash: string;
  state: UploadState;
  error?: "not-pdf" | "unreadable" | "password" | "unknown";
  duplicateGroup?: string;
  duplicateOf?: string[];
};

export type DocumentMatch = {
  requirementId: string;
  fileId: string;
  expiryDate?: string;
};

export type DocumentStatus =
  | "missing"
  | "expiry-needed"
  | "expired"
  | "not-provided"
  | "ok";

export type StatusCounts = {
  ok: number;
  missing: number;
  expiryNeeded: number;
  expired: number;
  notProvided: number;
  blocking: number;
  ready: number;
  total: number;
  mandatoryTotal: number;
};

export type ToastMessage = {
  id: string;
  type: "success" | "error" | "info";
  text: string;
};

export type AnalysisProgress = {
  active: boolean;
  label: string;
  done: number;
  total: number;
};

import type { Requirement, RequirementsFile, Tender } from "../types";

const REQUIRED_TENDER_FIELDS = [
  "tender_id",
  "title",
  "procuring_entity",
  "bidder",
  "submission_deadline",
] as const;

export class RequirementsParseError extends Error {}

function asString(value: unknown): string {
  if (typeof value === "string") return value.trim();
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return "";
}

/**
 * Parses and validates requirements.json entirely inside the browser.
 * Throws RequirementsParseError with a human readable message when invalid.
 */
export function parseRequirements(text: string): RequirementsFile {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    throw new RequirementsParseError("invalid-json");
  }

  if (!raw || typeof raw !== "object") throw new RequirementsParseError("invalid-json");

  const root = raw as Record<string, unknown>;
  const tenderRaw = root.tender;
  if (!tenderRaw || typeof tenderRaw !== "object") {
    throw new RequirementsParseError("missing-tender");
  }
  const t = tenderRaw as Record<string, unknown>;

  const tender: Tender = {
    tender_id: asString(t.tender_id),
    title: asString(t.title),
    procuring_entity: asString(t.procuring_entity),
    bidder: asString(t.bidder),
    submission_deadline: asString(t.submission_deadline),
  };

  for (const field of REQUIRED_TENDER_FIELDS) {
    if (!tender[field]) throw new RequirementsParseError(`missing-field:${field}`);
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(tender.submission_deadline)) {
    throw new RequirementsParseError("bad-date");
  }

  const list = root.requirements;
  if (!Array.isArray(list) || list.length === 0) {
    throw new RequirementsParseError("missing-requirements");
  }

  const seenIds = new Set<string>();
  const requirements: Requirement[] = list.map((item, index) => {
    if (!item || typeof item !== "object") {
      throw new RequirementsParseError(`bad-requirement:${index}`);
    }
    const r = item as Record<string, unknown>;
    const id = asString(r.id);
    const titleEn = asString(r.title_en);
    const order = Number(r.order);
    if (!id || !titleEn || !Number.isFinite(order)) {
      throw new RequirementsParseError(`bad-requirement:${index}`);
    }
    if (seenIds.has(id)) throw new RequirementsParseError(`duplicate-id:${id}`);
    seenIds.add(id);
    return {
      id,
      order,
      title_en: titleEn,
      title_bn: asString(r.title_bn) || titleEn,
      mandatory: r.mandatory === true,
      has_expiry: r.has_expiry === true,
    };
  });

  requirements.sort((a, b) => a.order - b.order || a.id.localeCompare(b.id));

  return { tender, requirements };
}

/**
 * Calendar-date helpers.
 *
 * All tender dates are stored as "YYYY-MM-DD" strings coming from the
 * requirements file. We compare normalised calendar dates (as UTC-midnight
 * timestamps) so a user's local timezone can never shift a day and turn an
 * "OK" document into an "Expired" one.
 */

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

export function isCalendarDate(value: string): boolean {
  const m = DATE_RE.exec(value);
  if (!m) return false;
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  if (month < 1 || month > 12 || day < 1 || day > 31) return false;
  const d = new Date(Date.UTC(year, month - 1, day));
  return (
    d.getUTCFullYear() === year &&
    d.getUTCMonth() === month - 1 &&
    d.getUTCDate() === day
  );
}

export function toUtcMillis(value: string): number | null {
  if (!isCalendarDate(value)) return null;
  const m = DATE_RE.exec(value)!;
  return Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
}

/**
 * -1 when a < b, 0 when equal, 1 when a > b, null when a date is invalid.
 */
export function compareDates(a: string, b: string): number | null {
  const ta = toUtcMillis(a);
  const tb = toUtcMillis(b);
  if (ta === null || tb === null) return null;
  return ta === tb ? 0 : ta < tb ? -1 : 1;
}

const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

const MONTHS_BN = [
  "জানুয়ারি",
  "ফেব্রুয়ারি",
  "মার্চ",
  "এপ্রিল",
  "মে",
  "জুন",
  "জুলাই",
  "আগস্ট",
  "সেপ্টেম্বর",
  "অক্টোবর",
  "নভেম্বর",
  "ডিসেম্বর",
];

/** "2026-10-20" -> "20 October 2026" (en) / "20 অক্টোবর 2026" (bn) */
export function formatDate(value: string, lang: "en" | "bn" = "en"): string {
  const m = DATE_RE.exec(value);
  if (!m) return value;
  const year = m[1];
  const month = Number(m[2]);
  const day = m[3];
  const monthName = lang === "bn" ? MONTHS_BN[month - 1] : MONTHS[month - 1];
  if (monthName === undefined) return value;
  return `${Number(day)} ${monthName} ${year}`;
}

export function todayIso(): string {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, "0");
  const d = String(now.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

import type {
  DocumentStatus,
  Requirement,
  StatusCounts,
  UploadedDocument,
} from "../types";
import { compareDates } from "./dates";

/**
 * THE single source of truth for requirement status.
 *
 * Rules (exactly one status per requirement):
 *  - missing           : mandatory requirement without a matched file   (blocking)
 *  - expiry-needed     : has_expiry + matched file + no expiry entered  (blocking)
 *  - expired           : expiry date < submission deadline              (blocking)
 *  - not-provided      : optional requirement without a matched file    (non blocking)
 *  - ok                : matched and (no expiry required or expiry >= deadline)
 *
 * When a date cannot be parsed at all we report "expiry-needed" so the user
 * is asked to correct it instead of silently passing validation.
 */
export function getRequirementStatus(
  requirement: Requirement,
  matchedFile: UploadedDocument | undefined,
  expiryDate: string | undefined,
  submissionDeadline: string
): DocumentStatus {
  if (!matchedFile) {
    return requirement.mandatory ? "missing" : "not-provided";
  }

  if (!requirement.has_expiry) return "ok";

  const expiry = (expiryDate ?? "").trim();
  if (!expiry) return "expiry-needed";

  const cmp = compareDates(expiry, submissionDeadline);
  if (cmp === null) return "expiry-needed";

  // expiry < deadline -> expired. Same day counts as valid.
  return cmp < 0 ? "expired" : "ok";
}

export const BLOCKING_STATUSES: DocumentStatus[] = [
  "missing",
  "expiry-needed",
  "expired",
];

export function isBlocking(status: DocumentStatus): boolean {
  return status === "missing" || status === "expiry-needed" || status === "expired";
}

export function summarize(counts: DocumentStatus[]): StatusCounts {
  const summary: StatusCounts = {
    ok: 0,
    missing: 0,
    expiryNeeded: 0,
    expired: 0,
    notProvided: 0,
    blocking: 0,
    ready: 0,
    total: counts.length,
    mandatoryTotal: 0,
  };
  for (const c of counts) {
    if (c === "ok") summary.ok++;
    else if (c === "missing") summary.missing++;
    else if (c === "expiry-needed") summary.expiryNeeded++;
    else if (c === "expired") summary.expired++;
    else summary.notProvided++;
  }
  summary.blocking =
    summary.missing + summary.expiryNeeded + summary.expired;
  summary.ready = summary.ok;
  return summary;
}

/** Package generation is allowed only when nothing blocks. */
export function canGeneratePackage(statuses: DocumentStatus[]): boolean {
  return statuses.every((s) => !isBlocking(s));
}

import type { UploadedDocument } from "../types";

/** SHA-256 via the browser Web Crypto API - content, not filename. */
export async function sha256(data: ArrayBuffer): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", data);
  const bytes = new Uint8Array(digest);
  let hex = "";
  for (let i = 0; i < bytes.length; i++) {
    hex += bytes[i].toString(16).padStart(2, "0");
  }
  return hex;
}

/**
 * Groups documents whose binary content is byte-for-byte identical.
 * Files in the same group are duplicates of each other even when their
 * filenames differ.
 */
export function applyDuplicateGroups(
  docs: UploadedDocument[]
): { docs: UploadedDocument[]; duplicateGroups: string[][] } {
  const byHash = new Map<string, UploadedDocument[]>();
  for (const doc of docs) {
    if (!doc.hash || doc.state === "error") continue;
    const list = byHash.get(doc.hash) ?? [];
    list.push(doc);
    byHash.set(doc.hash, list);
  }

  const groups: string[][] = [];
  const groupOf = new Map<string, string>();

  for (const [hash, list] of byHash) {
    if (list.length > 1) {
      const groupId = `dup-${hash.slice(0, 12)}`;
      groups.push(list.map((d) => d.id));
      for (const d of list) groupOf.set(d.id, groupId);
    }
  }

  const updated = docs.map((doc) => {
    const groupId = groupOf.get(doc.id);
    if (!groupId) {
      const { duplicateGroup: _drop, duplicateOf: _drop2, ...rest } = doc;
      return rest as UploadedDocument;
    }
    const partners = docs
      .filter(
        (d) => d.id !== doc.id && groupOf.get(d.id) === groupId && d.state !== "error"
      )
      .map((d) => d.name);
    return { ...doc, duplicateGroup: groupId, duplicateOf: partners };
  });

  return { docs: updated, duplicateGroups: groups };
}

/**
 * A duplicate group may only ever be matched once: if "license.pdf" is used
 * for Trade License, "license-copy.pdf" cannot be used for another
 * requirement. Returns true when the document is free to be matched.
 */
export function isAvailableForMatching(
  doc: UploadedDocument,
  matches: Record<string, { fileId: string; expiryDate?: string }>,
  allDocs: UploadedDocument[]
): boolean {
  if (doc.state !== "ready") return false;
  const matchedFileIds = new Set(Object.values(matches).map((m) => m.fileId));
  if (matchedFileIds.has(doc.id)) return true; // itself already matched

  if (!doc.duplicateGroup) return true;

  const groupMembers = allDocs.filter((d) => d.duplicateGroup === doc.duplicateGroup);
  const groupHasMatch = groupMembers.some((m) => matchedFileIds.has(m.id));
  return !groupHasMatch;
}

export const MAX_FILES = 30;
export const MAX_TOTAL_BYTES = 50 * 1024 * 1024; // 50 MB
export const PDF_MAGIC = "%PDF-";

export function isPdfFile(file: File): boolean {
  const name = file.name.toLowerCase();
  const type = (file.type || "").toLowerCase();
  if (type === "application/pdf") return true;
  if (name.endsWith(".pdf")) return true;
  return false;
}

export function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes < 0) return "0 KB";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export type FileRejection =
  | "not-pdf"
  | "too-many"
  | "too-large"
  | null;

/** Validates one file against type / count / total-size limits. */
export function validateIncoming(
  incoming: File[],
  currentCount: number,
  currentSize: number
): { accepted: File[]; rejections: { file: File; reason: NonNullable<FileRejection> }[] } {
  const accepted: File[] = [];
  const rejections: { file: File; reason: NonNullable<FileRejection> }[] = [];
  let count = currentCount;
  let size = currentSize;

  for (const file of incoming) {
    if (!isPdfFile(file)) {
      rejections.push({ file, reason: "not-pdf" });
      continue;
    }
    if (count + 1 > MAX_FILES) {
      rejections.push({ file, reason: "too-many" });
      continue;
    }
    if (size + file.size > MAX_TOTAL_BYTES) {
      rejections.push({ file, reason: "too-large" });
      continue;
    }
    accepted.push(file);
    count += 1;
    size += file.size;
  }

  return { accepted, rejections };
}

import { PDFDocument } from "pdf-lib";
import * as pdfjsLib from "pdfjs-dist";
import workerUrl from "pdfjs-dist/build/pdf.worker.min.mjs?url";

export type PdfReadError = "password" | "unreadable" | "unknown";

export class PdfReadFailure extends Error {
  constructor(public reason: PdfReadError) {
    super(reason);
    this.name = "PdfReadFailure";
  }
}

let workerConfigured = false;
function ensureWorker(): void {
  if (workerConfigured) return;
  try {
    pdfjsLib.GlobalWorkerOptions.workerSrc = workerUrl;
  } catch {
    // ignore - pdf-lib fallback below still gives a page count
  }
  workerConfigured = true;
}

/** Cheap structural check so obviously wrong files fail fast. */
function hasPdfHeader(bytes: Uint8Array): boolean {
  const head = new TextDecoder("latin1").decode(bytes.subarray(0, 1024));
  return head.includes("%PDF-");
}

function looksEncrypted(bytes: Uint8Array): boolean {
  const tail = new TextDecoder("latin1").decode(
    bytes.subarray(Math.max(0, bytes.length - 4096))
  );
  return tail.includes("/Encrypt");
}

async function countPagesWithPdfJs(buffer: ArrayBuffer): Promise<number> {
  ensureWorker();
  const task = pdfjsLib.getDocument({
    // pdf.js transfers the buffer to its worker - hand it a copy so the
    // caller's data stays usable.
    data: buffer.slice(0),
    isEvalSupported: false,
    useSystemFonts: false,
  });
  try {
    const doc = await task.promise;
    const pages = doc.numPages;
    await doc.destroy();
    return pages;
  } finally {
    try {
      await task.destroy();
    } catch {
      /* already destroyed */
    }
  }
}

async function countPagesWithPdfLib(buffer: ArrayBuffer): Promise<number> {
  const doc = await PDFDocument.load(new Uint8Array(buffer.slice(0)), {
    ignoreEncryption: false,
    updateMetadata: false,
  });
  return doc.getPageCount();
}

/**
 * Reads a local PDF entirely in the browser and returns its page count.
 * Never sends the file anywhere.
 */
export async function readPdfPageCount(file: File): Promise<number> {
  let buffer: ArrayBuffer;
  try {
    buffer = await file.arrayBuffer();
  } catch {
    throw new PdfReadFailure("unreadable");
  }

  const bytes = new Uint8Array(buffer);
  if (!hasPdfHeader(bytes)) throw new PdfReadFailure("unreadable");

  try {
    return await countPagesWithPdfJs(buffer);
  } catch (err) {
    const message = err instanceof Error ? `${err.name} ${err.message}` : String(err);
    if (message.includes("Password") || message.includes("password")) {
      throw new PdfReadFailure("password");
    }
    // Fallback parser: still a browser-compatible PDF engine.
    try {
      return await countPagesWithPdfLib(buffer);
    } catch (fallbackErr) {
      const fallbackMsg =
        fallbackErr instanceof Error ? fallbackErr.message : String(fallbackErr);
      if (/encrypt/i.test(fallbackMsg) || looksEncrypted(bytes)) {
        throw new PdfReadFailure("password");
      }
      throw new PdfReadFailure("unreadable");
    }
  }
}

/** Fresh bytes for a document, read at generation time. */
export async function readPdfBytes(file: File): Promise<Uint8Array> {
  const buffer = await file.arrayBuffer();
  return new Uint8Array(buffer);
}

import type { Requirement, UploadedDocument } from "../types";

export type MatchSuggestion = {
  requirementId: string;
  fileId: string;
  score: number;
};

const STOP_WORDS = new Set([
  "pdf",
  "copy",
  "final",
  "new",
  "doc",
  "document",
  "file",
  "scan",
  "scanned",
  "signed",
  "original",
  "2024",
  "2025",
  "2026",
  "2027",
]);

export function normalizeToken(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/\.[a-z0-9]{1,5}$/i, "")
    .replace(/[^a-z0-9\u0980-\u09ff]+/gi, " ")
    .split(/\s+/)
    .filter((t) => t.length > 1 && !STOP_WORDS.has(t));
}

function similarity(a: string, b: string): number {
  if (!a || !b || a === b) return a === b ? 1 : 0;
  if (a.includes(b) || b.includes(a)) return 0.9;
  // Dice coefficient over character bigrams
  const bigrams = (s: string) => {
    const set = new Map<string, number>();
    for (let i = 0; i < s.length - 1; i++) {
      const g = s.slice(i, i + 2);
      set.set(g, (set.get(g) ?? 0) + 1);
    }
    return set;
  };
  const A = bigrams(a);
  const B = bigrams(b);
  let overlap = 0;
  let totalA = 0;
  let totalB = 0;
  for (const [, n] of A) totalA += n;
  for (const [g, n] of B) {
    totalB += n;
    overlap += Math.min(n, A.get(g) ?? 0);
  }
  if (totalA + totalB === 0) return 0;
  return (2 * overlap) / (totalA + totalB);
}

/**
 * Bonus auto-match: suggests file -> requirement pairs by comparing file
 * names with requirement titles. Suggestions are NEVER applied automatically;
 * the user has to confirm each one.
 */
export function suggestMatches(
  requirements: Requirement[],
  docs: UploadedDocument[],
  existingMatches: Record<string, { fileId: string; expiryDate?: string }>
): MatchSuggestion[] {
  const usedFiles = new Set(Object.values(existingMatches).map((m) => m.fileId));
  const suggestions: MatchSuggestion[] = [];

  const available = docs.filter(
    (d) => d.state === "ready" && !usedFiles.has(d.id) && !d.duplicateGroup
  );

  for (const req of requirements) {
    if (existingMatches[req.id]) continue;
    let best: { fileId: string; score: number } | null = null;
    const titleTokens = normalizeToken(req.title_en);
    const titleKey = titleTokens.join(" ");

    for (const doc of available) {
      if (suggestions.some((s) => s.fileId === doc.id)) continue;
      const fileTokens = normalizeToken(doc.name);
      const fileKey = fileTokens.join(" ");
      if (!fileKey || !titleKey) continue;

      let score = similarity(fileKey, titleKey);
      // token overlap boost
      const shared = titleTokens.filter((t) => fileTokens.includes(t)).length;
      const denom = Math.max(titleTokens.length, 1);
      score = Math.max(score, shared / denom);

      if (score >= 0.6 && (!best || score > best.score)) {
        best = { fileId: doc.id, score };
      }
    }

    if (best) {
      suggestions.push({ requirementId: req.id, fileId: best.fileId, score: best.score });
      available.filter(() => false);
    }
  }

  return suggestions.sort((a, b) => b.score - a.score);
}

