import {
  PDFDocument,
  PDFFont,
  PDFPage,
  StandardFonts,
  degrees,
  rgb,
  type RGB,
} from "pdf-lib";
import type { Requirement, Tender, UploadedDocument } from "../types";
import { readPdfBytes } from "./pdfParser";
import { formatDate } from "./dates";

export type GenerationInput = {
  tender: Tender;
  requirements: Requirement[]; // already sorted by order
  matches: Record<string, { fileId: string; expiryDate?: string }>;
  docs: UploadedDocument[];
  includeIndex: boolean;
  onProgress?: (label: string, done: number, total: number) => void;
};

export type GenerationResult = { bytes: Uint8Array; fileName: string; pageCount: number };

/* ---------------------------------------------------------------- layout */

const A4_W = 595.28;
const A4_H = 841.89;
const MARGIN = 56;
/** Reserved bottom band (pt) used for the footer so it never covers content. */
const FOOTER_BAND = 26;
const CONTENT_BOTTOM = FOOTER_BAND + 14;

const NAVY = rgb(0.09, 0.1, 0.31);
const ACCENT = rgb(0.14, 0.22, 0.9);
const GRAY = rgb(0.4, 0.45, 0.56);
const LIGHT = rgb(0.85, 0.87, 0.91);
const INK = rgb(0.1, 0.11, 0.15);

function fitText(text: string, font: PDFFont, size: number, maxWidth: number): string {
  if (!text) return "";
  try {
    if (font.widthOfTextAtSize(text, size) <= maxWidth) return text;
  } catch {
    return text;
  }
  let out = text;
  while (out.length > 1) {
    out = out.slice(0, -1);
    try {
      if (font.widthOfTextAtSize(`${out}...`, size) <= maxWidth) return `${out}...`;
    } catch {
      return out;
    }
  }
  return "...";
}

type CoverData = {
  tender: Tender;
  items: { order: string; title: string; pages: number }[];
  createdOn: string;
};

/** Draws the English cover page(s). Returns the pages it created. */
function drawCover(doc: PDFDocument, font: PDFFont, bold: PDFFont, data: CoverData): PDFPage[] {
  const pages: PDFPage[] = [];
  let page = doc.addPage([A4_W, A4_H]);
  pages.push(page);

  // Header band
  page.drawRectangle({ x: 0, y: A4_H - 150, width: A4_W, height: 150, color: NAVY });
  page.drawRectangle({ x: 0, y: A4_H - 154, width: A4_W, height: 4, color: ACCENT });

  page.drawText("TENDER DOCUMENT PACKAGE", {
    x: MARGIN,
    y: A4_H - 74,
    size: 23,
    font: bold,
    color: rgb(1, 1, 1),
  });
  page.drawText("Prepared automatically with TenderPack Builder", {
    x: MARGIN,
    y: A4_H - 96,
    size: 10,
    font,
    color: rgb(0.78, 0.82, 0.95),
  });
  page.drawText(fitText(data.tender.tender_id, bold, 12, A4_W - MARGIN * 2), {
    x: MARGIN,
    y: A4_H - 126,
    size: 12,
    font: bold,
    color: rgb(1, 1, 1),
  });

  // Fields
  const fields: [string, string][] = [
    ["TENDER ID", data.tender.tender_id],
    ["TENDER TITLE", data.tender.title],
    ["PROCURING ENTITY", data.tender.procuring_entity],
    ["BIDDER", data.tender.bidder],
    ["SUBMISSION DEADLINE", formatDate(data.tender.submission_deadline, "en")],
    ["PACKAGE CREATED", data.createdOn],
  ];

  let y = A4_H - 150 - 46;
  for (const [label, value] of fields) {
    if (y - 30 < CONTENT_BOTTOM) break;
    page.drawText(label, {
      x: MARGIN,
      y,
      size: 7.5,
      font: bold,
      color: GRAY,
    });
    page.drawText(fitText(value, bold, 12.5, A4_W - MARGIN * 2), {
      x: MARGIN,
      y: y - 17,
      size: 12.5,
      font: bold,
      color: INK,
    });
    y -= 40;
  }

  // Included documents
  y -= 10;
  const heading = "INCLUDED DOCUMENTS";
  page.drawText(heading, { x: MARGIN, y, size: 11, font: bold, color: NAVY });
  page.drawLine({
    start: { x: MARGIN, y: y - 8 },
    end: { x: A4_W - MARGIN, y: y - 8 },
    thickness: 0.8,
    color: LIGHT,
  });
  y -= 30;

  const rowH = 19;
  const nextY = A4_H - 150 - 46 - 20; // continuation page start
  for (const item of data.items) {
    if (y < CONTENT_BOTTOM) {
      page = doc.addPage([A4_W, A4_H]);
      pages.push(page);
      page.drawText(`${heading} (continued)`, {
        x: MARGIN,
        y: A4_H - 60,
        size: 11,
        font: bold,
        color: NAVY,
      });
      page.drawLine({
        start: { x: MARGIN, y: A4_H - 68 },
        end: { x: A4_W - MARGIN, y: A4_H - 68 },
        thickness: 0.8,
        color: LIGHT,
      });
      y = A4_H - 100;
    }
    page.drawText(item.order, {
      x: MARGIN,
      y,
      size: 10,
      font: bold,
      color: ACCENT,
    });
    page.drawText(fitText(item.title, font, 10.5, A4_W - MARGIN * 2 - 70), {
      x: MARGIN + 34,
      y,
      size: 10.5,
      font,
      color: INK,
    });
    page.drawText(`${item.pages} ${item.pages === 1 ? "page" : "pages"}`, {
      x: A4_W - MARGIN - 54,
      y,
      size: 9,
      font,
      color: GRAY,
    });
    y -= rowH;
  }

  void nextY;
  return pages;
}

type IndexData = {
  entries: { title: string; page: number }[];
};

/** Draws the bonus index page(s) with correct final page numbers. */
function drawIndex(doc: PDFDocument, font: PDFFont, bold: PDFFont, data: IndexData): PDFPage[] {
  const pages: PDFPage[] = [];
  let page = doc.addPage([A4_W, A4_H]);
  pages.push(page);

  page.drawText("DOCUMENT INDEX", {
    x: MARGIN,
    y: A4_H - 74,
    size: 18,
    font: bold,
    color: NAVY,
  });
  page.drawText("Starting page of every document inside this package", {
    x: MARGIN,
    y: A4_H - 94,
    size: 9.5,
    font,
    color: GRAY,
  });
  page.drawLine({
    start: { x: MARGIN, y: A4_H - 106 },
    end: { x: A4_W - MARGIN, y: A4_H - 106 },
    thickness: 1,
    color: LIGHT,
  });

  page.drawText("DOCUMENT", { x: MARGIN, y: A4_H - 130, size: 8, font: bold, color: GRAY });
  page.drawText("STARTS ON PAGE", {
    x: A4_W - MARGIN - 92,
    y: A4_H - 130,
    size: 8,
    font: bold,
    color: GRAY,
  });

  let y = A4_H - 156;
  const rowH = 20;
  for (const entry of data.entries) {
    if (y < CONTENT_BOTTOM) {
      page = doc.addPage([A4_W, A4_H]);
      pages.push(page);
      y = A4_H - 74;
    }
    page.drawText(fitText(entry.title, font, 10.5, A4_W - MARGIN * 2 - 110), {
      x: MARGIN,
      y,
      size: 10.5,
      font,
      color: INK,
    });
    const label = String(entry.page);
    page.drawText(label, {
      x: A4_W - MARGIN - 10 - bold.widthOfTextAtSize(label, 10.5),
      y,
      size: 10.5,
      font: bold,
      color: ACCENT,
    });
    page.drawLine({
      start: { x: MARGIN, y: y - 6 },
      end: { x: A4_W - MARGIN, y: y - 6 },
      thickness: 0.4,
      color: LIGHT,
    });
    y -= rowH;
  }

  return pages;
}

/* ------------------------------------------------------------ source page */

function rotationOf(page: PDFPage): number {
  try {
    const raw = page.getRotation().angle;
    const norm = ((Math.round(raw) % 360) + 360) % 360;
    return norm === 90 || norm === 180 || norm === 270 ? norm : 0;
  } catch {
    return 0;
  }
}

/**
 * Copies one source page into the output and reserves a safe footer band
 * underneath it, so the footer can never overlap existing content.
 * The original page rotation is baked into the new page.
 */
async function copyPageWithFooterBand(dest: PDFDocument, srcPage: PDFPage): Promise<void> {
  const embedded = await dest.embedPage(srcPage);
  const ew = embedded.width;
  const eh = embedded.height;
  const r = rotationOf(srcPage);
  const swap = r === 90 || r === 270;
  const destW = swap ? eh : ew;
  const destH = (swap ? ew : eh) + FOOTER_BAND;
  const page = dest.addPage([destW, destH]);

  let x = 0;
  let y = 0;
  if (r === 0) {
    x = 0;
    y = FOOTER_BAND;
  } else if (r === 90) {
    x = 0;
    y = ew + FOOTER_BAND;
  } else if (r === 180) {
    x = ew;
    y = eh + FOOTER_BAND;
  } else {
    x = eh;
    y = FOOTER_BAND;
  }

  page.drawPage(embedded, { x, y, rotate: degrees(-r) });
}

/* --------------------------------------------------------------- generate */

export async function generatePackage(input: GenerationInput): Promise<GenerationResult> {
  const { tender, requirements, matches, docs, includeIndex, onProgress } = input;
  const progress = onProgress ?? (() => {});

  const docById = new Map(docs.map((d) => [d.id, d]));
  const included: { req: Requirement; doc: UploadedDocument }[] = [];
  for (const req of requirements) {
    const match = matches[req.id];
    if (!match) continue;
    const doc = docById.get(match.fileId);
    if (!doc || doc.state !== "ready") continue;
    included.push({ req, doc });
  }

  const createdOn = formatDate(new Date().toISOString().slice(0, 10), "en");

  // Pass 1 - read every source document once to learn its real page count.
  const counts = new Map<string, number>();
  let done = 0;
  for (const { doc } of included) {
    progress("Reading documents", done, included.length);
    const bytes = await readPdfBytes(doc.file);
    const src = await PDFDocument.load(bytes, {
      ignoreEncryption: true,
      updateMetadata: false,
    });
    counts.set(doc.id, src.getPageCount());
    done += 1;
  }
  progress("Reading documents", included.length, included.length);

  const coverData: CoverData = {
    tender,
    createdOn,
    items: included.map((entry, i) => ({
      order: String(i + 1).padStart(2, "0"),
      title: entry.req.title_en,
      pages: counts.get(entry.doc.id) ?? entry.doc.pages,
    })),
  };

  // Cover + index page counts are needed before page numbers can be computed,
  // so draw them once into a scratch document purely to measure them.
  const scratch = await PDFDocument.create();
  const sFont = await scratch.embedFont(StandardFonts.Helvetica);
  const sBold = await scratch.embedFont(StandardFonts.HelveticaBold);
  const coverPages = drawCover(scratch, sFont, sBold, coverData).length;
  const indexPages = includeIndex
    ? drawIndex(
        scratch,
        sFont,
        sBold,
        {
          entries: included.map((entry, i) => ({
            title: entry.req.title_en,
            page:
              coverPages +
              (includeIndex ? 1 : 0) +
              1 +
              included
                .slice(0, i)
                .reduce((sum, prev) => sum + (counts.get(prev.doc.id) ?? prev.doc.pages), 0),
          })),
        }
      ).length
    : 0;

  const headerPages = coverPages + indexPages;
  const startPages = new Map<string, number>();
  let cursor = headerPages + 1;
  for (const entry of included) {
    startPages.set(entry.req.id, cursor);
    cursor += counts.get(entry.doc.id) ?? entry.doc.pages;
  }
  const totalPages = cursor - 1;

  // Pass 2 - build the real package.
  const out = await PDFDocument.create();
  const font = await out.embedFont(StandardFonts.Helvetica);
  const bold = await out.embedFont(StandardFonts.HelveticaBold);

  progress("Building cover", 0, 1);
  drawCover(out, font, bold, coverData);

  if (includeIndex) {
    drawIndex(out, font, bold, {
      entries: included.map((entry) => ({
        title: entry.req.title_en,
        page: startPages.get(entry.req.id) ?? 1,
      })),
    });
  }

  done = 0;
  for (const { req, doc } of included) {
    progress(`Adding ${req.title_en}`, done, included.length);
    const bytes = await readPdfBytes(doc.file);
    const src = await PDFDocument.load(bytes, {
      ignoreEncryption: true,
      updateMetadata: false,
    });
    const pageCount = src.getPageCount();
    for (let i = 0; i < pageCount; i++) {
      await copyPageWithFooterBand(out, src.getPage(i));
    }
    done += 1;
  }
  progress("Adding documents", included.length, included.length);

  // Footer on EVERY page: "<TENDER_ID> | Page X of Y"
  const footerText = (n: number) => `${tender.tender_id} | Page ${n} of ${totalPages}`;
  const pages = out.getPages();
  progress("Adding footers", 0, pages.length);
  pages.forEach((page, index) => {
    const label = footerText(index + 1);
    const size = 8;
    let width = 0;
    try {
      width = font.widthOfTextAtSize(label, size);
    } catch {
      width = 0;
    }
    const w = page.getWidth();
    const x = Math.max(8, (w - width) / 2);
    page.drawText(label, {
      x,
      y: 9,
      size,
      font,
      color: rgb(0.35, 0.39, 0.47),
    });
  });
  progress("Adding footers", pages.length, pages.length);

  progress("Saving package", 0, 1);
  const bytes = await out.save({ useObjectStreams: true });
  progress("Saving package", 1, 1);

  const safeId = tender.tender_id.replace(/[^\w.-]+/g, "_") || "Tender";
  return {
    bytes,
    fileName: `${safeId}_Package.pdf`,
    pageCount: pages.length,
  };
}

export function downloadBytes(bytes: Uint8Array, fileName: string): void {
  const copy = new Uint8Array(bytes.byteLength);
  copy.set(bytes);
  const blob = new Blob([copy], { type: "application/pdf" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

