import { createContext, useContext, useMemo, useState, type ReactNode } from "react";
import { en, type Dict } from "./en";
import { bn } from "./bn";
import type { Lang } from "../types";

type I18nContextValue = {
  lang: Lang;
  setLang: (lang: Lang) => void;
  t: Dict;
  /** Translate with "{placeholder}" substitution. */
  tf: (key: keyof Dict, params: Record<string, string | number>) => string;
  /** Requirement title in the active language. */
  titleOf: (titleEn: string, titleBn: string) => string;
};

const I18nContext = createContext<I18nContextValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLang] = useState<Lang>("en");

  const value = useMemo<I18nContextValue>(() => {
    const t: Dict = lang === "bn" ? bn : en;
    return {
      lang,
      setLang,
      t,
      tf: (key, params) => {
        const raw = t[key];
        if (typeof raw !== "string") return String(raw);
        return raw.replace(/\{(\w+)\}/g, (m, name: string) =>
          name in params ? String(params[name]) : m
        );
      },
      titleOf: (titleEn, titleBn) => (lang === "bn" && titleBn ? titleBn : titleEn),
    };
  }, [lang]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nContextValue {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error("useI18n must be used inside I18nProvider");
  return ctx;
}

