  const title = titleOf(requirement.title_en, requirement.title_bn);
  const showExpiry = requirement.has_expiry && Boolean(matchedDoc);
  const needsExpiry = status === "expiry-needed";

  return (
    <li
      className={`fade-in rounded-xl border bg-white px-3 py-3 transition-colors sm:px-4 ${
        status === "ok" || status === "not-provided"
          ? "border-ink-200"
          : "border-rose-200"
      }`}
    >
      <div className="grid grid-cols-1 gap-3 lg:grid-cols-[46px_minmax(180px,1fr)_minmax(220px,1.1fr)_170px_150px] lg:items-start">
        {/* order */}
        <div className="flex items-center gap-2 lg:block">
          <span className="inline-flex h-8 w-8 items-center justify-center rounded-lg bg-ink-900 text-xs font-bold text-white">
            {String(requirement.order).padStart(2, "0")}
          </span>
        </div>

        {/* title + badges */}
        <div className="min-w-0">
          <div className="text-sm font-semibold leading-tight text-ink-900">{title}</div>
          <div className="mt-1.5 flex flex-wrap gap-1.5">
            <span
              className={`rounded-md px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide ${
                requirement.mandatory
                  ? "bg-brand-50 text-brand-700"
                  : "bg-ink-100 text-ink-500"
              }`}
            >
              {requirement.mandatory ? t.mandatory : t.optional}
            </span>
            {requirement.has_expiry ? (
              <span className="rounded-md bg-amber-50 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-amber-700">
                {t.needsExpiry}
              </span>
            ) : null}
            {matchedDoc?.duplicateGroup ? (
              <span className="rounded-md bg-orange-50 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-orange-700">
                {t.duplicateTitle}
              </span>
            ) : null}
          </div>
        </div>

        {/* file select */}
        <div className="min-w-0">
          <label className="label" htmlFor={`file-${requirement.id}`}>
            {t.matchedFile}
          </label>
          <div className="flex items-center gap-1.5">
            <select
              id={`file-${requirement.id}`}
              className="input flex-1 appearance-auto py-1.5 text-[13px]"
              value={matchedDoc?.id ?? ""}
              onChange={(event) => onBind(event.target.value)}
            >
              <option value="">{t.noFile}</option>
              {options.map((opt) => (
                <option key={opt.id} value={opt.id} disabled={opt.disabled}>
                  {opt.label}
                  {opt.note ? ` — ${opt.note}` : ""}
                </option>
              ))}
            </select>
            {matchedDoc ? (
              <button
                type="button"
                className="rounded-md border border-ink-200 p-1.5 text-ink-400 hover:bg-rose-50 hover:text-rose-600"
                onClick={onUnbind}
                aria-label={`${t.undoMatch}: ${title}`}
                title={t.undoMatch}
              >
                <Link2Off size={15} aria-hidden />
              </button>
            ) : null}
          </div>
          {matchedDoc ? (
            <div className="mt-1 truncate text-[11px] text-ink-400" title={matchedDoc.name}>
              {matchedDoc.name} · {matchedDoc.pages} {matchedDoc.pages === 1 ? t.page : t.pages} ·{" "}
              {formatBytes(matchedDoc.size)}
            </div>
          ) : null}
          {suggestion ? (
            <div className="mt-1.5 flex items-center gap-2 rounded-md border border-brand-200 bg-brand-50 px-2 py-1.5 text-[11px] text-brand-800">
              <Sparkles size={13} aria-hidden />
              <span className="truncate">
                {t.suggestions}: <strong>{suggestion.fileName}</strong>
              </span>
              <button
                type="button"
                className="ml-auto shrink-0 rounded bg-brand-600 px-2 py-0.5 text-[10px] font-bold text-white hover:bg-brand-700"
                onClick={onAcceptSuggestion}
              >
                {t.accept}
              </button>
            </div>
          ) : null}
        </div>

        {/* expiry */}
        <div className="min-w-0">
          {showExpiry ? (
            <>
              <label className="label" htmlFor={`expiry-${requirement.id}`}>
                {t.expiryDate}
              </label>
              <input
                id={`expiry-${requirement.id}`}
                type="date"
                className={`input py-1.5 text-[13px] ${
                  needsExpiry || status === "expired"
                    ? "border-amber-400 bg-amber-50/40"
                    : ""
                }`}
                value={expiryDate ?? ""}
                onChange={(event) => onExpiryChange(event.target.value)}
                aria-invalid={status === "expired"}
              />
              {status === "expired" ? (
                <div className="mt-1 flex items-center gap-1 text-[11px] font-semibold text-rose-600">
                  <CalendarDays size={12} aria-hidden />
                  {t.statusExpired}
                </div>
              ) : null}
            </>
          ) : (
            <div className="text-[11px] leading-relaxed text-ink-300">
              {requirement.has_expiry ? "—" : t.expiryHint}
            </div>
          )}
        </div>

        {/* status */}
        <div className="flex items-center justify-between gap-2 lg:justify-end">
          <StatusBadge status={status} />
        </div>
      </div>
    </li>
  );
}

import { ClipboardList } from "lucide-react";
import type {
  DocumentStatus,
  Requirement,
  UploadedDocument,
} from "../types";
import { useI18n } from "../i18n";
import RequirementRow, { type FileOption } from "./RequirementRow";

type MatchMap = Record<string, { fileId: string; expiryDate?: string }>;

type Props = {
  requirements: Requirement[];
  docs: UploadedDocument[];
  matches: MatchMap;
  statuses: Record<string, DocumentStatus>;
  suggestions: { requirementId: string; fileId: string }[];
  onBind: (requirementId: string, fileId: string) => void;
  onUnbind: (requirementId: string) => void;
  onExpiryChange: (requirementId: string, value: string) => void;
  onAcceptSuggestion: (requirementId: string, fileId: string) => void;
};

export default function RequirementsList({
  requirements,
  docs,
  matches,
  statuses,
  suggestions,
  onBind,
  onUnbind,
  onExpiryChange,
  onAcceptSuggestion,
}: Props) {
  const { t } = useI18n();

  const readyDocs = docs.filter((d) => d.state === "ready");

  const buildOptions = (currentFileId?: string): FileOption[] => {
    const usedFileIds = new Set(
      Object.values(matches)
        .map((m) => m.fileId)
        .filter((id) => id !== currentFileId)
    );

    return readyDocs.map((doc) => {
      const usedElsewhere = usedFileIds.has(doc.id);
      let duplicateBlocked = false;
      if (!usedElsewhere && doc.duplicateGroup && doc.id !== currentFileId) {
        duplicateBlocked = readyDocs.some(
          (d) =>
            d.duplicateGroup === doc.duplicateGroup &&
            d.id !== doc.id &&
            usedFileIds.has(d.id)
        );
      }
      const disabled = usedElsewhere || duplicateBlocked;
      return {
        id: doc.id,
        label: `${doc.name} (${doc.pages} ${doc.pages === 1 ? t.page : t.pages})`,
        disabled,
        note: duplicateBlocked
          ? t.duplicateTitle
          : usedElsewhere
            ? t.matched
            : undefined,
      };
    });
  };

  if (requirements.length === 0) {
    return (
      <section className="card flex flex-col items-center justify-center px-6 py-14 text-center">
        <div className="mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-ink-100 text-ink-400">
          <ClipboardList size={22} aria-hidden />
        </div>
        <h2 className="text-base font-bold text-ink-800">{t.emptyRequirements}</h2>
        <p className="mt-1 max-w-sm text-sm text-ink-500">{t.emptyRequirementsHint}</p>
      </section>
    );
  }

  return (
    <section className="card p-3 sm:p-4" aria-labelledby="requirements-heading">
      <div className="mb-3 flex flex-wrap items-center justify-between gap-2 px-1">
        <h2 id="requirements-heading" className="card-title">
          {t.requirements}
        </h2>
        <span className="text-[11px] text-ink-400">{t.requirementsHint}</span>
      </div>

      <ul className="flex flex-col gap-2">
        {requirements.map((req) => {
          const match = matches[req.id];
          const matchedDoc = match ? docs.find((d) => d.id === match.fileId) : undefined;
          const suggestion = suggestions.find((s) => s.requirementId === req.id);
          const suggestionDoc = suggestion
            ? docs.find((d) => d.id === suggestion.fileId)
            : undefined;

          return (
            <RequirementRow
              key={req.id}
              requirement={req}
              status={statuses[req.id] ?? (req.mandatory ? "missing" : "not-provided")}
              matchedDoc={matchedDoc}
              options={buildOptions(match?.fileId)}
              expiryDate={match?.expiryDate}
              suggestion={
                suggestionDoc
                  ? { fileId: suggestionDoc.id, fileName: suggestionDoc.name }
                  : undefined
              }
              onBind={(fileId) => onBind(req.id, fileId)}
              onUnbind={() => onUnbind(req.id)}
              onExpiryChange={(value) => onExpiryChange(req.id, value)}
              onAcceptSuggestion={() =>
                suggestion ? onAcceptSuggestion(req.id, suggestion.fileId) : undefined
              }
            />
          );
        })}
      </ul>
    </section>
  );
}

import { useRef, useState } from "react";
import { FileUp, UploadCloud } from "lucide-react";
import { useI18n } from "../i18n";
import { MAX_FILES, MAX_TOTAL_BYTES, formatBytes } from "../lib/validators";

type Props = {
  onFiles: (files: File[]) => void;
  disabled?: boolean;
  busy?: boolean;
};

export default function FileUploader({ onFiles, disabled, busy }: Props) {
  const { t } = useI18n();
  const [dragging, setDragging] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFiles = (list: FileList | null) => {
    if (!list || list.length === 0) return;
    onFiles(Array.from(list));
  };

  return (
    <div>
      <button
        type="button"
        disabled={disabled || busy}
        onClick={() => inputRef.current?.click()}
        onDragOver={(event) => {
          event.preventDefault();
          if (!disabled && !busy) setDragging(true);
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(event) => {
          event.preventDefault();
          setDragging(false);
          if (disabled || busy) return;
          handleFiles(event.dataTransfer?.files ?? null);
        }}
        className={`flex w-full flex-col items-center justify-center gap-1.5 rounded-xl border-2 border-dashed px-4 py-7 text-center transition-colors focus-visible:ring-2 focus-visible:ring-brand-500 ${
          dragging
            ? "border-brand-500 bg-brand-50"
            : "border-ink-200 bg-ink-50/50 hover:border-brand-300 hover:bg-brand-50/40"
        } ${disabled ? "opacity-60" : ""}`}
        aria-label={t.dropHere}
      >
        <span className="text-brand-600">
          {dragging ? <UploadCloud size={26} aria-hidden /> : <FileUp size={24} aria-hidden />}
        </span>
        <span className="text-sm font-semibold text-ink-700">{t.dropHere}</span>
        <span className="text-xs text-ink-400">{t.orBrowse}</span>
        <span className="mt-1 text-[11px] font-medium text-ink-400">{t.limits}</span>
        <span className="text-[11px] text-ink-300">
          {formatBytes(MAX_TOTAL_BYTES)} · {MAX_FILES} × {t.filesCount.replace("{n}", "")}
        </span>
      </button>

      <input
        ref={inputRef}
        type="file"
        accept="application/pdf,.pdf"
        multiple
        className="hidden"
        onChange={(event) => {
          handleFiles(event.target.files);
          event.target.value = "";
        }}
      />
    </div>
  );
}

