import { FileText, Loader2, Trash2, TriangleAlert, ShieldAlert } from "lucide-react";
import type { Requirement, UploadedDocument } from "../types";
import { useI18n } from "../i18n";
import { formatBytes } from "../lib/validators";

type MatchMap = Record<string, { fileId: string; expiryDate?: string }>;

type Props = {
  docs: UploadedDocument[];
  requirements: Requirement[];
  matches: MatchMap;
  onRemove: (fileId: string) => void;
};

function errorMessage(key: UploadedDocument["error"], fallback: string): string {
  if (key === "password") return "PASSWORD";
  if (key === "unreadable" || key === "not-pdf") return "UNREADABLE";
  return fallback;
}

export default function UploadedFiles({ docs, requirements, matches, onRemove }: Props) {
  const { t, titleOf } = useI18n();

  if (docs.length === 0) {
    return (
      <div className="rounded-lg border border-dashed border-ink-200 bg-ink-50/50 px-4 py-6 text-center">
        <div className="text-sm font-semibold text-ink-600">{t.noFiles}</div>
        <div className="mt-1 text-xs text-ink-400">{t.noFilesHint}</div>
      </div>
    );
  }

  const totalSize = docs.reduce((sum, d) => sum + d.size, 0);
  const matchedByFile = new Map<string, string>();
  for (const [reqId, match] of Object.entries(matches)) {
    matchedByFile.set(match.fileId, reqId);
  }

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center justify-between px-0.5 text-[11px] font-semibold text-ink-400">
        <span>{t.filesCount.replace("{n}", String(docs.length))}</span>
        <span>{formatBytes(totalSize)}</span>
      </div>

      <ul className="flex max-h-[420px] flex-col gap-2 overflow-y-auto pr-1">
        {docs.map((doc) => {
          const reqId = matchedByFile.get(doc.id);
          const req = reqId ? requirements.find((r) => r.id === reqId) : undefined;
          const reading = doc.state === "reading";
          const errorLabel =
            doc.state === "error"
              ? doc.error === "password"
                ? t.passwordProtected
                : doc.error === "not-pdf"
                  ? t.notPdf
                  : t.unreadable
              : "";

          return (
            <li
              key={doc.id}
              className="fade-in rounded-lg border border-ink-200 bg-white px-3 py-2.5"
            >
              <div className="flex items-start gap-2.5">
                <span
                  className={`mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-md ${
                    doc.state === "error"
                      ? "bg-rose-50 text-rose-600"
                      : "bg-brand-50 text-brand-600"
                  }`}
                >
                  <FileText size={16} aria-hidden />
                </span>

                <div className="min-w-0 flex-1">
                  <div className="truncate text-[13px] font-semibold text-ink-800" title={doc.name}>
                    {doc.name}
                  </div>
                  <div className="mt-0.5 flex flex-wrap items-center gap-x-2 gap-y-0.5 text-[11px] text-ink-400">
                    {reading ? (
                      <span className="inline-flex items-center gap-1 text-brand-600">
                        <Loader2 size={11} className="animate-spin" aria-hidden />
                        {t.analyzing}
                      </span>
                    ) : doc.state === "ready" ? (
                      <>
                        <span>
                          {doc.pages} {doc.pages === 1 ? t.page : t.pages}
                        </span>
                        <span aria-hidden>·</span>
                        <span>{formatBytes(doc.size)}</span>
                      </>
                    ) : (
                      <span className="font-semibold text-rose-600">{errorLabel}</span>
                    )}
                  </div>

                  {req ? (
                    <div className="mt-1 inline-flex max-w-full items-center gap-1 rounded bg-emerald-50 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-700">
                      <span className="truncate">
                        {t.matched}: {titleOf(req.title_en, req.title_bn)}
                      </span>
                    </div>
                  ) : null}

                  {doc.duplicateOf && doc.duplicateOf.length > 0 ? (
                    <div className="mt-1.5 rounded-md border border-orange-200 bg-orange-50 px-2 py-1.5 text-[11px] leading-snug text-orange-800">
                      <div className="flex items-center gap-1 font-bold">
                        <TriangleAlert size={12} aria-hidden />
                        {t.duplicateTitle}
                      </div>
                      <div className="mt-0.5">
                        {t.duplicateBody} <strong>{doc.duplicateOf.join(", ")}</strong>
                      </div>
                    </div>
                  ) : null}

                  {doc.state === "error" ? (
                    <div className="mt-1.5 flex items-start gap-1 rounded-md border border-rose-200 bg-rose-50 px-2 py-1.5 text-[11px] leading-snug text-rose-700">
                      <ShieldAlert size={12} className="mt-0.5 shrink-0" aria-hidden />
                      <span>{errorLabel}</span>
                    </div>
                  ) : null}
                </div>

                <button
                  type="button"
                  onClick={() => onRemove(doc.id)}
                  className="shrink-0 rounded-md p-1.5 text-ink-400 transition-colors hover:bg-rose-50 hover:text-rose-600"
                  aria-label={`${t.remove}: ${doc.name}`}
                  title={t.remove}
                >
                  <Trash2 size={15} aria-hidden />
                </button>
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

