import { CircleCheck, CircleDashed, Loader2, TriangleAlert, XCircle } from "lucide-react";
import type { StatusCounts } from "../types";
import { useI18n } from "../i18n";

type Props = {
  counts: StatusCounts;
  canGenerate: boolean;
};

export default function ValidationSummary({ counts, canGenerate }: Props) {
  const { t, tf } = useI18n();

  const rows = [
    {
      key: "ok",
      icon: <CircleCheck size={14} aria-hidden />,
      label: t.okCount,
      value: counts.ok,
      className: "text-emerald-700",
      show: counts.ok > 0,
    },
    {
      key: "expiry",
      icon: <TriangleAlert size={14} aria-hidden />,
      label: t.expiryNeededCount,
      value: counts.expiryNeeded,
      className: "text-amber-700",
      show: counts.expiryNeeded > 0,
    },
    {
      key: "expired",
      icon: <XCircle size={14} aria-hidden />,
      label: t.expiredCount,
      value: counts.expired,
      className: "text-rose-700",
      show: counts.expired > 0,
    },
    {
      key: "missing",
      icon: <XCircle size={14} aria-hidden />,
      label: t.missingCount,
      value: counts.missing,
      className: "text-rose-700",
      show: counts.missing > 0,
    },
    {
      key: "optional",
      icon: <CircleDashed size={14} aria-hidden />,
      label: t.optionalNotProvided,
      value: counts.notProvided,
      className: "text-ink-500",
      show: counts.notProvided > 0,
    },
  ];

  return (
    <section className="card p-4" aria-labelledby="readiness-heading">
      <div className="mb-3 flex items-center justify-between">
        <h2 id="readiness-heading" className="card-title">
          {t.readiness}
        </h2>
        <span
          className={`rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide ${
