import {
  CheckCircle2,
  Download,
  FileDown,
  Loader2,
  Lock,
  PackageCheck,
} from "lucide-react";
import { useI18n } from "../i18n";

export type GenerationState = {
  active: boolean;
  label: string;
  done: number;
  total: number;
};

export type GeneratedResult = {
  fileName: string;
  pageCount: number;
};

type Props = {
  canGenerate: boolean;
  blockingCount: number;
  includeIndex: boolean;
  onIncludeIndexChange: (value: boolean) => void;
  onGenerate: () => void;
  onDownload: () => void;
  onExport: (format: "csv" | "xlsx") => void;
  generating: GenerationState;
  result: GeneratedResult | null;
  hasRequirements: boolean;
};

export default function GenerateButton({
  canGenerate,
  blockingCount,
  includeIndex,
  onIncludeIndexChange,
  onGenerate,
  onDownload,
  onExport,
  generating,
  result,
  hasRequirements,
}: Props) {
  const { t, tf } = useI18n();
  const pct =
    generating.total > 0 ? Math.round((generating.done / generating.total) * 100) : 0;

  return (
    <section className="card p-4" aria-labelledby="generate-heading">
      <h2 id="generate-heading" className="card-title mb-3">
        {t.generate}
      </h2>

      <label className="mb-3 flex cursor-pointer items-center gap-2 rounded-lg border border-ink-200 px-3 py-2 text-[12px] font-medium text-ink-600 hover:bg-ink-50">
        <input
          type="checkbox"
          className="h-3.5 w-3.5 accent-brand-600"
          checked={includeIndex}
          onChange={(event) => onIncludeIndexChange(event.target.checked)}
        />
        {t.includeIndex}
      </label>

      <button
        type="button"
        className="btn-primary w-full"
        disabled={!canGenerate || generating.active || !hasRequirements}
        onClick={onGenerate}
      >
        {generating.active ? (
          <>
            <Loader2 size={16} className="animate-spin" aria-hidden />
            {t.generating}
          </>
        ) : result ? (
          <>
            <PackageCheck size={16} aria-hidden />
            {t.generate}
          </>
        ) : canGenerate ? (
          <>
            <PackageCheck size={16} aria-hidden />
            {t.generate}
          </>
        ) : (
          <>
            <Lock size={15} aria-hidden />
            {tf("fixBlocking", { n: blockingCount })}
          </>
        )}
      </button>

      {!canGenerate && blockingCount === 0 && hasRequirements ? (
        <p className="mt-2 text-center text-[11px] text-ink-400">{t.emptyRequirementsHint}</p>
      ) : null}

      {generating.active ? (
        <div className="mt-3">
          <div className="flex items-center justify-between text-[11px] font-semibold text-ink-500">
            <span className="truncate pr-2">{generating.label}</span>
            <span>{pct}%</span>
          </div>
          <div className="mt-1 h-2 w-full overflow-hidden rounded-full bg-ink-100">
            <div
              className="progress-stripe h-full rounded-full bg-brand-600 transition-all duration-200"
              style={{ width: `${pct}%` }}
            />
          </div>
        </div>
      ) : null}

      {result && !generating.active ? (
        <div className="mt-3 rounded-lg border border-emerald-200 bg-emerald-50 p-3">
          <div className="flex items-center gap-1.5 text-[12px] font-bold text-emerald-700">
            <CheckCircle2 size={14} aria-hidden />
            {t.generated}
          </div>
          <div className="mt-0.5 truncate text-[11px] text-emerald-700" title={result.fileName}>
            {tf("savedAs", { name: result.fileName })} · {result.pageCount}{" "}
            {result.pageCount === 1 ? t.page : t.pages}
          </div>
          <button type="button" className="btn-primary mt-2 w-full" onClick={onDownload}>
            <Download size={15} aria-hidden />
            {t.download}
          </button>
        </div>
      ) : null}

      <div className="mt-3 grid grid-cols-2 gap-2">
        <button
          type="button"
          className="btn-secondary px-2 text-[12px]"
          onClick={() => onExport("csv")}
        >
          <FileDown size={14} aria-hidden />
          CSV
        </button>
        <button
          type="button"
          className="btn-secondary px-2 text-[12px]"
          onClick={() => onExport("xlsx")}
        >
          <FileDown size={14} aria-hidden />
          Excel
        </button>
      </div>
    </section>
  );
}

import type { DocumentStatus, Requirement, UploadedDocument } from "../types";

type MatchMap = Record<string, { fileId: string; expiryDate?: string }>;

export type ChecklistRow = {
  document: string;
  fileName: string;
  pages: string;
  expiryDate: string;
  status: DocumentStatus;
};

export function buildChecklist(
  requirements: Requirement[],
  docs: UploadedDocument[],
  matches: MatchMap,
  statusOf: (requirementId: string) => DocumentStatus,
  titles: (req: Requirement) => string
): ChecklistRow[] {
  const byId = new Map(docs.map((d) => [d.id, d]));
  return requirements.map((req) => {
    const match = matches[req.id];
    const doc = match ? byId.get(match.fileId) : undefined;
    return {
      document: `${req.order}. ${titles(req)}`,
      fileName: doc?.name ?? "",
      pages: doc ? String(doc.pages) : "",
      expiryDate: match?.expiryDate ?? "",
      status: statusOf(req.id),
    };
  });
}

function escapeCsv(value: string): string {
  return `"${value.replace(/"/g, '""')}"`;
}

function downloadBlob(blob: Blob, fileName: string): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  document.body.removeChild(anchor);
  setTimeout(() => URL.revokeObjectURL(url), 3000);
}

export function exportCsv(rows: ChecklistRow[], baseName: string): void {
  const header = ["Document", "File Name", "Pages", "Expiry Date", "Status"];
  const lines = [
    header.map(escapeCsv).join(","),
    ...rows.map((row) =>
      [row.document, row.fileName, row.pages, row.expiryDate, row.status]
        .map(escapeCsv)
        .join(",")
    ),
  ];
  // UTF-8 BOM so Excel opens Bangla text correctly.
  const blob = new Blob(["\uFEFF" + lines.join("\r\n")], {
    type: "text/csv;charset=utf-8;",
  });
  downloadBlob(blob, `${baseName}_Checklist.csv`);
}

export function exportExcel(rows: ChecklistRow[], baseName: string): void {
  const statusLabel: Record<DocumentStatus, string> = {
    ok: "OK",
    missing: "Missing",
    "expiry-needed": "Expiry date needed",
    expired: "Expired",
    "not-provided": "Not provided",
  };
  const header = "<tr><th>Document</th><th>File Name</th><th>Pages</th><th>Expiry Date</th><th>Status</th></tr>";
  const body = rows
    .map(
      (row) =>
        `<tr><td>${escapeHtml(row.document)}</td><td>${escapeHtml(row.fileName)}</td><td>${escapeHtml(
          row.pages
        )}</td><td>${escapeHtml(row.expiryDate)}</td><td>${statusLabel[row.status]}</td></tr>`
    )
    .join("");
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body><table border="1">${header}${body}</table></body></html>`;
  const blob = new Blob(["\uFEFF" + html], { type: "application/vnd.ms-excel;charset=utf-8;" });
  downloadBlob(blob, `${baseName}_Checklist.xls`);
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

import { Lock, ShieldCheck, X } from "lucide-react";
import { useI18n } from "../i18n";

type Props = {
  onClose: () => void;
};

export default function HelpModal({ onClose }: Props) {
  const { t } = useI18n();

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-ink-950/40 p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="help-title"
      onClick={onClose}
    >
      <div
        className="fade-in w-full max-w-lg rounded-2xl border border-ink-200 bg-white p-6 shadow-xl"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="mb-4 flex items-start justify-between gap-4">
          <div>
            <h2 id="help-title" className="text-lg font-bold text-ink-900">
              {t.helpTitle}
            </h2>
            <p className="text-xs text-ink-400">{t.appTagline}</p>
          </div>
          <button
            type="button"
            className="rounded-lg p-1.5 text-ink-400 hover:bg-ink-100"
            onClick={onClose}
            aria-label={t.close}
          >
            <X size={18} aria-hidden />
          </button>
        </div>

        <ol className="flex flex-col gap-2 text-sm leading-relaxed text-ink-700">
          {t.helpBody.map((line, index) => (
            <li key={index}>{line}</li>
          ))}
        </ol>

        <div className="mt-5 rounded-xl border border-emerald-200 bg-emerald-50 p-4">
          <div className="flex items-center gap-2 text-sm font-bold text-emerald-800">
            <Lock size={15} aria-hidden />
            {t.helpPrivacyTitle}
          </div>
          <div className="mt-1.5 flex items-start gap-2 text-[13px] leading-relaxed text-emerald-800">
            <ShieldCheck size={15} className="mt-0.5 shrink-0" aria-hidden />
            <span>{t.helpPrivacyBody}</span>
          </div>
        </div>

        <button type="button" className="btn-primary mt-5 w-full" onClick={onClose}>
          {t.close}
        </button>
      </div>
    </div>
  );
}

