import RequirementsList from "./components/RequirementsList";
import FileUploader from "./components/FileUploader";
import UploadedFiles from "./components/UploadedFiles";
import ValidationSummary from "./components/ValidationSummary";
import GenerateButton, {
  type GeneratedResult,
  type GenerationState,
} from "./components/GenerateButton";
import Toast from "./components/Toast";

import { I18nProvider, useI18n } from "./i18n";
import type {
  AnalysisProgress,
  DocumentStatus,
  Requirement,
  Tender,
  ToastMessage,
  UploadedDocument,
} from "./types";

import {
  parseRequirements,
  RequirementsParseError,
} from "./lib/requirementsParser";
import { readPdfPageCount, PdfReadFailure } from "./lib/pdfParser";
import { applyDuplicateGroups, sha256 } from "./lib/duplicateDetector";
import {
  canGeneratePackage,
  getRequirementStatus,
  summarize,
} from "./lib/statusEngine";
import { validateIncoming } from "./lib/validators";
import { suggestMatches } from "./lib/autoMatch";
import {
  downloadBytes,
  generatePackage,
} from "./lib/packageGenerator";
import { buildChecklist, exportCsv, exportExcel } from "./lib/exportChecklist";

type MatchMap = Record<string, { fileId: string; expiryDate?: string }>;

const IDLE_ANALYSIS: AnalysisProgress = { active: false, label: "", done: 0, total: 0 };
const IDLE_GENERATION: GenerationState = { active: false, label: "", done: 0, total: 0 };

function newId(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
  }
}

function Workspace() {
  const { t, tf, titleOf } = useI18n();

  const [tender, setTender] = useState<Tender | null>(null);
  const [requirements, setRequirements] = useState<Requirement[]>([]);
  const [docs, setDocs] = useState<UploadedDocument[]>([]);
  const [matches, setMatches] = useState<MatchMap>({});
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisProgress>(IDLE_ANALYSIS);
  const [generating, setGenerating] = useState<GenerationState>(IDLE_GENERATION);
  const [result, setResult] = useState<GeneratedResult | null>(null);
  const generatedBytes = useRef<Uint8Array | null>(null);
  const [dismissedSuggestions, setDismissedSuggestions] = useState<string[]>([]);
  const [includeIndex, setIncludeIndex] = useState(true);
  const [showHelp, setShowHelp] = useState(false);
  const requirementsInputRef = useRef<HTMLInputElement>(null);

  /* ------------------------------------------------------------- toasts */

  const toast = useCallback((type: ToastMessage["type"], text: string) => {
    const id = newId();
    setToasts((prev) => [...prev.slice(-3), { id, type, text }]);
    window.setTimeout(() => {
      setToasts((prev) => prev.filter((item) => item.id !== id));
    }, 5200);
  }, []);

  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((item) => item.id !== id));
  }, []);

  /* -------------------------------------------------- requirements.json */

  const loadRequirements = useCallback(
    async (file: File) => {
      try {
        const text = await file.text();
        const parsed = parseRequirements(text);
        setTender(parsed.tender);
        setRequirements(parsed.requirements);
        setMatches({});
        setResult(null);
        generatedBytes.current = null;
        setDismissedSuggestions([]);
        toast("success", `${parsed.tender.tender_id} — ${parsed.tender.title}`);
      } catch (error) {
        const detail =
          error instanceof RequirementsParseError ? error.message : "unknown";
        console.warn("requirements.json rejected:", detail);
        toast("error", t.loadError);
      }
    },
    [t.loadError, toast]
  );

  /* ---------------------------------------------------------- PDF upload */

  const analyzeFiles = useCallback(
    async (incoming: File[]) => {
      const current = docs;
      const currentSize = current.reduce((sum, d) => sum + d.size, 0);
      const { accepted, rejections } = validateIncoming(
        incoming,
        current.length,
        currentSize
      );

      for (const rejection of rejections) {
        const message =
          rejection.reason === "not-pdf"
            ? t.notPdf
            : rejection.reason === "too-many"
              ? t.tooMany
              : t.tooLarge;
        toast("error", `${rejection.file.name}: ${message}`);
      }

      if (accepted.length === 0) return;

      const placeholders: UploadedDocument[] = accepted.map((file) => ({
        id: newId(),
        file,
        name: file.name,
        size: file.size,
        pages: 0,
        hash: "",
        state: "reading",
      }));

      setDocs((prev) => [...prev, ...placeholders]);
      setAnalysis({
        active: true,
        label: t.analyzing,
        done: 0,
        total: placeholders.length,
      });

      const patch = (id: string, next: Partial<UploadedDocument>) => {
        setDocs((prev) => prev.map((d) => (d.id === id ? { ...d, ...next } : d)));
      };

      let done = 0;
      for (const placeholder of placeholders) {
        try {
          const buffer = await placeholder.file.arrayBuffer();
          const hash = await sha256(buffer);
          patch(placeholder.id, { hash });
        } catch {
          patch(placeholder.id, { hash: "" });
        }

        try {
          const pages = await readPdfPageCount(placeholder.file);
          patch(placeholder.id, { pages, state: "ready" });
        } catch (error) {
          const reason =
            error instanceof PdfReadFailure ? error.reason : "unknown";
          patch(placeholder.id, {
            state: "error",
            error: reason === "password" ? "password" : "unreadable",
            pages: 0,
          });
        }

        done += 1;
        setAnalysis({
          active: true,
          label: t.analyzing,
          done,
          total: placeholders.length,
        });
      }

      // Recompute duplicate groups over the whole collection.
      setDocs((prev) => applyDuplicateGroups(prev).docs);
      setAnalysis({ ...IDLE_ANALYSIS });
    },
    [docs, t.analyzing, t.notPdf, t.tooMany, t.tooLarge, toast]
  );

  const handleIncomingFiles = useCallback(
    (files: File[]) => {
      void analyzeFiles(files);
    },
    [analyzeFiles]
  );

  const removeDoc = useCallback((fileId: string) => {
    setDocs((prev) => applyDuplicateGroups(prev.filter((d) => d.id !== fileId)).docs);
    setMatches((prev) => {
      const next: MatchMap = {};
      for (const [reqId, match] of Object.entries(prev)) {
        if (match.fileId !== fileId) next[reqId] = match;
      }
      return next;
    });
    setResult(null);
    generatedBytes.current = null;
  }, []);

  /* ----------------------------------------------------------- matching */

  const bind = useCallback((requirementId: string, fileId: string) => {
    if (!fileId) {
      setMatches((prev) => {
        const next = { ...prev };
        delete next[requirementId];
        return next;
      });
      return;
    }
    setMatches((prev) => {
      const next: MatchMap = {};
      for (const [reqId, match] of Object.entries(prev)) {
        // a file can only ever belong to one requirement
        if (reqId !== requirementId && match.fileId !== fileId) next[reqId] = match;
      }
      const existing = prev[requirementId];
      next[requirementId] = { fileId, expiryDate: existing?.expiryDate };
      return next;
    });
    setResult(null);
    generatedBytes.current = null;
  }, []);

  const unbind = useCallback((requirementId: string) => {
    setMatches((prev) => {
      const next = { ...prev };
      delete next[requirementId];
      return next;
    });
    setResult(null);
    generatedBytes.current = null;
  }, []);

  const changeExpiry = useCallback((requirementId: string, value: string) => {
    setMatches((prev) => {
      const existing = prev[requirementId];
      if (!existing) return prev;
      return { ...prev, [requirementId]: { ...existing, expiryDate: value } };
    });
    setResult(null);
    generatedBytes.current = null;
  }, []);

  /* ------------------------------------------------------------- status */

  const statuses = useMemo(() => {
    const map: Record<string, DocumentStatus> = {};
    const byId = new Map(docs.map((d) => [d.id, d]));
    const deadline = tender?.submission_deadline ?? "";
    for (const req of requirements) {
      const match = matches[req.id];
      map[req.id] = getRequirementStatus(
        req,
        match ? byId.get(match.fileId) : undefined,
        match?.expiryDate,
        deadline
      );
    }
    return map;
  }, [requirements, docs, matches, tender]);

  const statusList = useMemo(
    () => requirements.map((req) => statuses[req.id]).filter(Boolean),
    [requirements, statuses]
  );
  const counts = useMemo(() => summarize(statusList), [statusList]);
  const canGenerate = useMemo(
    () => tender !== null && requirements.length > 0 && canGeneratePackage(statusList),
    [tender, requirements.length, statusList]
  );

  const suggestions = useMemo(() => {
    if (!tender) return [];
    return suggestMatches(requirements, docs, matches).filter(
      (s) => !dismissedSuggestions.includes(`${s.requirementId}:${s.fileId}`)
    );
  }, [tender, requirements, docs, matches, dismissedSuggestions]);

  /* ---------------------------------------------------------- generation */

  const generate = useCallback(async () => {
    if (!tender || requirements.length === 0) return;
    setGenerating({ active: true, label: t.generate, done: 0, total: 1 });
    try {
      const generated = await generatePackage({
        tender,
        requirements,
        matches,
        docs,
        includeIndex,
        onProgress: (label, done, total) =>
          setGenerating({ active: true, label, done, total }),
      });
      generatedBytes.current = generated.bytes;
      setResult({ fileName: generated.fileName, pageCount: generated.pageCount });
      downloadBytes(generated.bytes, generated.fileName);
      toast("success", `${t.generated}: ${generated.fileName}`);
    } catch (error) {
      console.error(
        "package generation failed:",
        error instanceof Error ? error.message : String(error)
      );
      toast("error", t.generateFailed);
    } finally {
      setGenerating({ ...IDLE_GENERATION });
    }
  }, [tender, requirements, matches, docs, includeIndex, t, toast]);

  const download = useCallback(() => {
    if (!generatedBytes.current || !result) return;
    downloadBytes(generatedBytes.current, result.fileName);
  }, [result]);

  const exportChecklist = useCallback(
    (format: "csv" | "xlsx") => {
      if (requirements.length === 0 || !tender) return;
      const rows = buildChecklist(
        requirements,
        docs,
        matches,
        (reqId) => statuses[reqId] ?? "not-provided",
        (req) => titleOf(req.title_en, req.title_bn)
      );
      const base = tender.tender_id.replace(/[^\w.-]+/g, "_") || "Tender";
      if (format === "csv") exportCsv(rows, base);
      else exportExcel(rows, base);
      toast("success", t.exported);
    },
    [requirements, tender, docs, matches, statuses, titleOf, t.exported, toast]
  );

  /* -------------------------------------------------------------- reset */

  const resetAll = useCallback(() => {
    if (!window.confirm(t.resetConfirm)) return;
    setTender(null);
    setRequirements([]);
    setDocs([]);
    setMatches({});
    setResult(null);
    generatedBytes.current = null;
    setAnalysis({ ...IDLE_ANALYSIS });
    setGenerating({ ...IDLE_GENERATION });
    setDismissedSuggestions([]);
    toast("info", t.reset);
  }, [t.resetConfirm, t.reset, toast]);

  /* -------------------------------------------------------- workflow bar */

  const analyzing = analysis.active || docs.some((d) => d.state === "reading");
  const unmatched = requirements.filter((req) => !matches[req.id]).length;
  const activeStep = !tender
    ? 0
    : docs.length === 0
      ? 1
      : analyzing
        ? 2
        : unmatched > 0
          ? 3
          : counts.expiryNeeded > 0
            ? 4
            : counts.blocking > 0
              ? 6
              : result
                ? 8
                : 7;

  const steps = [
    { key: "s1", label: t.step1 },
    { key: "s2", label: t.step2 },
    { key: "s3", label: t.step3 },
    { key: "s4", label: t.step4 },
    { key: "s5", label: t.step5 },
    { key: "s6", label: t.step6 },
    { key: "s7", label: t.step7 },
    { key: "s8", label: t.step8 },
    { key: "s9", label: t.step9 },
  ];
  const stepStates: StepState[] = steps.map((_, index) =>
    index < activeStep ? "done" : index === activeStep ? "active" : "todo"
  );

  const totalSize = docs.reduce((sum, d) => sum + d.size, 0);
  const pct = analysis.total > 0 ? Math.round((analysis.done / analysis.total) * 100) : 0;

  /* --------------------------------------------------------------- view */

  return (
    <div className="flex min-h-full flex-col">
      <Header
        tenderId={tender?.tender_id}
        onHelp={() => setShowHelp(true)}
        onReset={resetAll}
      />

      <main className="mx-auto w-full max-w-[1600px] flex-1 px-4 py-5 sm:px-6">
        {/* workflow progress */}
        <div className="card overflow-x-auto px-4 py-3">
          <ProgressSteps steps={steps} states={stepStates} />
        </div>

        <div className="mt-4 grid grid-cols-1 gap-4 xl:grid-cols-[minmax(0,1fr)_400px]">
          {/* ------------------------------------------------ left column */}
          <div className="flex min-w-0 flex-col gap-4">
            {/* requirements loader */}
            <section className="card flex flex-wrap items-center justify-between gap-3 p-4">
              <div className="flex items-center gap-3">
                <span className="flex h-10 w-10 items-center justify-center rounded-lg bg-emerald-50 text-emerald-600">
                  <FileJson size={20} aria-hidden />
                </span>
                <div>
                  <div className="text-sm font-bold text-ink-900">
                    {t.loadRequirements}
                  </div>
                  <div className="text-[11px] text-ink-400">
                    {tender ? `${tender.requirementsCount ?? ""}` : ""}
                    {tender ? requirements.length : 0}
                    {tender ? ` · ${t.requirements}` : t.emptyRequirementsHint}
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  className="btn-primary"
                  onClick={() => requirementsInputRef.current?.click()}
                >
                  <Upload size={15} aria-hidden />
                  {tender ? t.changeRequirements : t.loadRequirements}
                </button>
                <input
                  ref={requirementsInputRef}
                  type="file"
                  accept="application/json,.json"
                  className="hidden"
                  onChange={(event) => {
                    const file = event.target.files?.[0];
                    if (file) void loadRequirements(file);
                    event.target.value = "";
                  }}
                />
              </div>
            </section>

            {tender ? (
              <TenderInfo tender={tender} />
            ) : (
              <section className="card flex flex-col items-center justify-center px-6 py-14 text-center">
                <div className="mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-ink-100 text-ink-400">
                  <FileJson size={22} aria-hidden />
                </div>
                <h2 className="text-base font-bold text-ink-800">
                  {t.emptyRequirements}
                </h2>
                <p className="mt-1 max-w-sm text-sm text-ink-500">
                  {t.emptyRequirementsHint}
                </p>
                <button
                  type="button"
                  className="btn-primary mt-4"
                  onClick={() => requirementsInputRef.current?.click()}
                >
                  <Upload size={15} aria-hidden />
                  {t.loadRequirements}
                </button>
              </section>
            )}

            {/* auto-match suggestions */}
            {suggestions.length > 0 ? (
              <div className="flex flex-wrap items-center gap-3 rounded-xl border border-brand-200 bg-brand-50 px-4 py-3">
                <span className="flex items-center gap-2 text-[13px] font-bold text-brand-800">
                  <Lightbulb size={15} aria-hidden />
                  {t.suggestions}
                  <span className="rounded-full bg-brand-600 px-1.5 py-0.5 text-[10px] text-white">
                    {suggestions.length}
                  </span>
                </span>
                <span className="text-[11px] text-brand-700">{t.suggestionsHint}</span>
                <div className="ml-auto flex gap-2">
                  <button
                    type="button"
                    className="btn-secondary bg-white px-2.5 py-1.5 text-[12px]"
                    onClick={() => {
                      setMatches((prev) => {
                        const next = { ...prev };
                        const used = new Set(
                          Object.values(prev).map((m) => m.fileId)
                        );
                        for (const s of suggestions) {
                          if (next[s.requirementId] || used.has(s.fileId)) continue;
                          next[s.requirementId] = { fileId: s.fileId };
                          used.add(s.fileId);
                        }
                        return next;
                      });
                      setResult(null);
                    }}
                  >
                    <Wand2 size={13} aria-hidden />
                    {t.autoMatchAll}
                  </button>
                  <button
                    type="button"
                    className="btn-ghost px-2.5 py-1.5 text-[12px]"
                    onClick={() =>
                      setDismissedSuggestions((prev) => [
                        ...prev,
                        ...suggestions.map((s) => `${s.requirementId}:${s.fileId}`),
                      ])
                    }
                  >
                    <X size={13} aria-hidden />
                    {t.dismiss}
                  </button>
                </div>
              </div>
            ) : null}

            <RequirementsList
              requirements={requirements}
              docs={docs}
              matches={matches}
              statuses={statuses}
              suggestions={suggestions}
              onBind={bind}
              onUnbind={unbind}
              onExpiryChange={changeExpiry}
              onAcceptSuggestion={(reqId, fileId) => bind(reqId, fileId)}
            />
          </div>

          {/* ----------------------------------------------- right column */}
          <aside className="flex flex-col gap-4">
            <section className="card p-4">
              <div className="mb-3 flex items-center justify-between">
                <h2 className="card-title">{t.upload}</h2>
                <span className="rounded-md bg-ink-100 px-1.5 py-0.5 text-[10px] font-bold text-ink-500">
                  {docs.length}/30
                </span>
              </div>

              <FileUploader
                onFiles={handleIncomingFiles}
                disabled={analyzing}
                busy={analyzing}
              />

              <div className="mt-3">
                <UploadedFiles
                  docs={docs}
                  requirements={requirements}
                  matches={matches}
                  onRemove={removeDoc}
                />
              </div>
            </section>

            <ValidationSummary counts={counts} canGenerate={canGenerate} />

            <GenerateButton
              canGenerate={canGenerate}
              blockingCount={counts.blocking}
              includeIndex={includeIndex}
              onIncludeIndexChange={setIncludeIndex}
              onGenerate={() => void generate()}
              onDownload={download}
              onExport={exportChecklist}
              generating={generating}
              result={result}
              hasRequirements={requirements.length > 0}
            />
          </aside>
        </div>

        {/* ------------------------------------------------- status footer */}
        <div className="card mt-4 flex flex-wrap items-center gap-4 px-4 py-3">
          <span className="flex items-center gap-2 text-[13px] font-bold text-ink-700">
            <Sparkles size={15} className="text-brand-600" aria-hidden />
            {analysis.active
              ? `${t.analyzing}…`
              : generating.active
                ? generating.label
                : t.footerBuilt}
          </span>

          {analysis.active ? (
            <div className="flex min-w-[240px] flex-1 items-center gap-3">
              <div className="h-2 flex-1 overflow-hidden rounded-full bg-ink-100">
                <div
                  className="progress-stripe h-full rounded-full bg-brand-600 transition-all"
                  style={{ width: `${pct}%` }}
                />
              </div>
              <span className="text-xs font-bold text-ink-500">{pct}%</span>
              <span className="text-[11px] text-ink-400">{t.analyzingHint}</span>
            </div>
          ) : (
            <div className="flex flex-wrap items-center gap-3 text-[11px] font-medium text-ink-400">
              <span>
                {docs.length} {t.step2} · {totalSize ? formatSize(totalSize) : "0 MB"}
              </span>
              <span>·</span>
              <span>{t.privacyNote}</span>
            </div>
          )}
        </div>
      </main>

      <Toast toasts={toasts} onDismiss={dismissToast} />
      {showHelp ? <HelpModal onClose={() => setShowHelp(false)} /> : null}
    </div>
  );
}

function formatSize(bytes: number): string {
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export default function App() {
  return (
    <I18nProvider>
      <Workspace />
    </I18nProvider>
  );
}

