/**
 * Creates the demo/sample tender pack used for manual + automated testing.
 * This script is TEST DATA only: the application itself never knows anything
 * about these files or requirement ids.
 *
 * Run: node scripts/makeSamplePack.mjs
 */
import { mkdirSync, writeFileSync, copyFileSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { PDFDocument, StandardFonts, rgb, degrees } from "pdf-lib";

const here = dirname(fileURLToPath(import.meta.url));
const outDir = join(here, "..", "sample-pack");
mkdirSync(outDir, { recursive: true });

const NAVY = rgb(0.1, 0.12, 0.35);
const GRAY = rgb(0.45, 0.45, 0.5);

const requirements = {
  tender: {
    tender_id: "T-2026-0417",
    title: "Supply of IT Equipment",
    procuring_entity: "Directorate of ICT, Ministry of Administration",
    bidder: "Acme Technologies Ltd.",
    submission_deadline: "2026-10-20",
  },
  requirements: [
