async function makePdf(fileName, title, pages) {
  const doc = await PDFDocument.create();
  const bold = await doc.embedFont(StandardFonts.HelveticaBold);
  const regular = await doc.embedFont(StandardFonts.Helvetica);

  for (let i = 0; i < pages; i++) {
    const page = doc.addPage([595, 842]);
    if (fileName === "experience_certificate.pdf" && i === 1) {
      page.setRotation(degrees(90));
    }
    page.drawRectangle({ x: 0, y: 782, width: 595, height: 60, color: NAVY });
    page.drawText(title, { x: 48, y: 805, size: 18, font: bold, color: rgb(1, 1, 1) });
    page.drawText(`Page ${i + 1} of ${pages}`, {
      x: 48,
      y: 755,
      size: 11,
      font: regular,
      color: GRAY,
    });
    for (let line = 0; line < 22; line++) {
      const width = 480 - ((line * 37) % 140);
      page.drawRectangle({
        x: 48,
        y: 715 - line * 28,
        width,
        height: 7,
        color: rgb(0.88, 0.89, 0.92),
      });
    }
    page.drawText("Sample document content generated for TenderPack Builder testing.", {
      x: 48,
      y: 60,
      size: 9,
      font: regular,
      color: GRAY,
    });
  }

  const bytes = await doc.save();
  writeFileSync(join(outDir, fileName), bytes);
  return bytes;
}

