/**
 * Generates the committed artefact  output/<tender_id>_Package.pdf
 * by running the SAME package generator the web app uses, against the sample
 * pack, after resolving every blocking issue exactly like a user would in the
 * UI (match documents + enter expiry dates).
 *
 * Run: npm run make:output
 */
import { mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { PDFDocument } from "pdf-lib";

import { parseRequirements } from "../src/lib/requirementsParser";
import { applyDuplicateGroups, sha256 } from "../src/lib/duplicateDetector";
import { canGeneratePackage, getRequirementStatus } from "../src/lib/statusEngine";
import { generatePackage } from "../src/lib/packageGenerator";
import type { UploadedDocument } from "../src/types";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const packDir = join(root, "sample-pack");
const outDir = join(root, "output");

/** Resolved state - what a user ends up with after fixing every problem. */
const RESOLVED_MATCHES: Record<string, { file: string; expiry?: string }> = {
  R01: { file: "trade_license.pdf", expiry: "2027-05-01" },
  R02: { file: "tin_certificate.pdf" },
  R03: { file: "vat_certificate.pdf" },
  R04: { file: "bank_solvency.pdf", expiry: "2026-12-31" },
  R05: { file: "experience_certificate.pdf" },
  R06: { file: "company_profile.pdf" },
  R08: { file: "manufacturer_authorization.pdf", expiry: "2027-08-31" },
  R09: { file: "iso_9001_certificate.pdf", expiry: "2028-03-31" },
  // R07 (optional) intentionally left without a document -> "not provided"
};

async function buildDocs(): Promise<{ docs: UploadedDocument[]; idByName: Map<string, string> }> {
  const entries = readdirSync(packDir).filter((n) => n.toLowerCase().endsWith(".pdf"));
  const docs: UploadedDocument[] = [];
  const idByName = new Map<string, string>();
  let i = 0;

  for (const name of entries) {
    const path = join(packDir, name);
    const bytes = readFileSync(path);
    const file = new File([new Uint8Array(bytes)], name, { type: "application/pdf" });
    const id = `file-${++i}`;
    idByName.set(name, id);

    let pages = 0;
    let state: UploadedDocument["state"] = "ready";
    try {
      const parsed = await PDFDocument.load(new Uint8Array(bytes), {
        updateMetadata: false,
      });
      pages = parsed.getPageCount();
    } catch {
      state = "error";
    }

    docs.push({
      id,
      file,
      name,
      size: file.size,
      pages,
      hash: state === "ready" ? await sha256(await file.arrayBuffer()) : "",
      state,
      error: state === "error" ? "unreadable" : undefined,
    });
  }

  return { docs: applyDuplicateGroups(docs).docs, idByName };
}

async function main() {
  const raw = readFileSync(join(packDir, "requirements.json"), "utf8");
  const { tender, requirements } = parseRequirements(raw);
  const { docs, idByName } = await buildDocs();

  const matches: Record<string, { fileId: string; expiryDate?: string }> = {};
  for (const req of requirements) {
    const resolved = RESOLVED_MATCHES[req.id];
    if (!resolved) continue;
    const fileId = idByName.get(resolved.file);
    if (!fileId) throw new Error(`Sample file missing: ${resolved.file}`);
    matches[req.id] = { fileId, expiryDate: resolved.expiry };
  }

  const byId = new Map(docs.map((d) => [d.id, d]));
  const statuses = requirements.map((req) => {
    const match = matches[req.id];
    return getRequirementStatus(
      req,
      match ? byId.get(match.fileId) : undefined,
      match?.expiryDate,
      tender.submission_deadline
    );
  });

  console.log("Requirement statuses:");
  requirements.forEach((req, i) => {
    const match = matches[req.id];
    console.log(
      `  ${String(req.order).padStart(2, "0")} ${req.title_en.padEnd(36)} ${
        (match ? byId.get(match.fileId)?.name ?? "-" : "-").padEnd(32)
      } ${statuses[i]}`
    );
  });

  if (!canGeneratePackage(statuses)) {
    throw new Error("The resolved sample still has blocking issues - fix RESOLVED_MATCHES.");
  }

  const result = await generatePackage({
    tender,
    requirements,
    matches,
    docs,
    includeIndex: true,
    onProgress: (label, done, total) =>
      process.stdout.write(`\r  ${label}: ${done}/${total}   `),
  });
  process.stdout.write("\n");

  mkdirSync(outDir, { recursive: true });
  const outPath = join(outDir, result.fileName);
  writeFileSync(outPath, result.bytes);

  const kb = (statSync(outPath).size / 1024).toFixed(0);
  console.log(`\n✔ ${outPath}`);
  console.log(`  ${result.pageCount} pages, ${kb} KB`);
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});

