/**
 * Quality check for the generated package.
 *
 * Verifies, on the final PDF bytes:
 *   1. cover page contains every tender field and the document list in order
 *   2. index page start numbers match the real page positions
 *   3. every page carries the footer "<TENDER_ID> | Page X of Y"
 *   4. the footer sits inside the reserved bottom band and never overlaps
 *      existing document content
 *   5. documents appear in requirement order, original page order preserved
 *
 * Run: npm run verify:output
 */
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import * as pdfjs from "pdfjs-dist/legacy/build/pdf.mjs";

const root = process.cwd();
const outDir = join(root, "output");

type Check = { name: string; pass: boolean; detail?: string };
const checks: Check[] = [];
function check(name: string, pass: boolean, detail?: string) {
  checks.push({ name, pass, detail });
}

const fileName = readdirSync(outDir).find((n) => n.endsWith("_Package.pdf"));
if (!fileName) {
  console.error("No output/<tender_id>_Package.pdf found. Run `npm run make:output` first.");
  process.exit(1);
}
const tenderId = fileName.replace("_Package.pdf", "");
const bytes = new Uint8Array(readFileSync(join(outDir, fileName)));

const doc = await pdfjs.getDocument({
  data: bytes,
  isEvalSupported: false,
  useSystemFonts: false,
  disableWorker: true as unknown as boolean,
}).promise;

const totalPages = doc.numPages;
const pageTexts: string[] = [];
const pageItems: { str: string; x: number; y: number; height: number }[][] = [];

for (let p = 1; p <= totalPages; p++) {
  const page = await doc.getPage(p);
  const content = await page.getTextContent();
  const items = content.items
    .filter((it): it is { str: string; transform: number[]; height: number } =>
      typeof (it as { str?: string }).str === "string"
    )
    .map((it) => ({
      str: it.str,
      x: it.transform[4],
      y: it.transform[5],
      height: it.height,
    }));
  pageTexts.push(items.map((i) => i.str).join(" "));
  pageItems.push(items);
}

/* ---------------------------------------------------------- 1. cover */

const cover = pageTexts[0] ?? "";
check("cover: tender id", cover.includes(tenderId));
check("cover: title", cover.includes("Supply of IT Equipment"));
check("cover: procuring entity", cover.includes("Directorate of ICT"));
check("cover: bidder", cover.includes("Acme Technologies Ltd."));
check("cover: submission deadline", cover.includes("20 October 2026"));
check("cover: package created date", /Package Created \d/.test(cover.replace(/\s+/g, " ")));
check("cover: document list heading", cover.includes("INCLUDED DOCUMENTS"));

const coverOrder = [
  "Trade License",
  "TIN Certificate",
  "VAT Registration Certificate",
  "Bank Solvency Certificate",
  "Experience Certificate",
  "Company Profile",
  "Manufacturer's Authorization Letter",
  "ISO 9001 Certificate",
];
let last = -1;
let orderOk = true;
for (const name of coverOrder) {
  const idx = cover.indexOf(name);
  if (idx < 0 || idx < last) orderOk = false;
  last = Math.max(last, idx);
}
check("cover: documents listed in requirement order", orderOk);
check(
  "cover: optional missing document skipped",
  !cover.includes("Audited Financial Statement"),
  "R07 has no file and must not be listed"
);

/* ---------------------------------------------------------- 2. index */

const index = (pageTexts[1] ?? "").replace(/\s+/g, " ");
const expectedIndex: [string, number][] = [
  ["Trade License", 3],
  ["TIN Certificate", 6],
  ["VAT Registration Certificate", 8],
  ["Bank Solvency Certificate", 10],
  ["Experience Certificate", 12],
  ["Company Profile", 16],
  ["Manufacturer's Authorization Letter", 21],
  ["ISO 9001 Certificate", 23],
];
check("index: heading present", index.includes("DOCUMENT INDEX"));
let indexOk = true;
for (const [name, page] of expectedIndex) {
  const re = new RegExp(`${name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s+${page}\\b`);
  if (!re.test(index)) indexOk = false;
}
check("index: every start page is correct", indexOk, index.slice(0, 400));

/* --------------------------------------------------------- 3. footer */

let footersOk = true;
const badPages: number[] = [];
for (let p = 1; p <= totalPages; p++) {
  const expected = `${tenderId} | Page ${p} of ${totalPages}`;
  if (!pageTexts[p - 1].includes(expected)) {
    footersOk = false;
    badPages.push(p);
  }
}
check(
  `footer: "<id> | Page X of Y" on all ${totalPages} pages`,
  footersOk,
  badPages.length ? `missing on pages ${badPages.join(", ")}` : undefined
);

/* ---------------------------------------- 4. footer never covers content */

let overlap = false;
const overlapPages: number[] = [];
for (let p = 1; p <= totalPages; p++) {
  const items = pageItems[p - 1];
  const footerItems = items.filter((i) => i.str.includes(`| Page ${p} of`));
  if (footerItems.length === 0) continue;
  const footerY = Math.min(...footerItems.map((i) => i.y));
  const contentItems = items.filter((i) => !i.str.includes(`| Page ${p} of`));
  const minContentY = Math.min(...contentItems.map((i) => i.y - i.height * 0.4));
  if (contentItems.length > 0 && minContentY < footerY + 10) {
    overlap = true;
    overlapPages.push(p);
  }
}
check("footer: sits in its own reserved band (no overlap)", !overlap, overlapPages.join(", "));

/* --------------------------------------- 5. document order / page order */

const expectedDocPages: [string, number, string][] = [
  ["Trade License", 3, "TRADE LICENSE"],
  ["TIN Certificate", 6, "TIN CERTIFICATE"],
  ["VAT Registration Certificate", 8, "VAT REGISTRATION CERTIFICATE"],
  ["Bank Solvency Certificate", 10, "BANK SOLVENCY CERTIFICATE"],
  ["Experience Certificate", 12, "EXPERIENCE CERTIFICATE"],
  ["Company Profile", 16, "COMPANY PROFILE"],
  ["Manufacturer's Authorization Letter", 21, "MANUFACTURER AUTHORIZATION"],
  ["ISO 9001 Certificate", 23, "ISO 9001 CERTIFICATE"],
];
let docOk = true;
const details: string[] = [];
for (const [name, startPage, marker] of expectedDocPages) {
  const text = (pageTexts[startPage - 1] ?? "").replace(/\s+/g, " ");
  if (!text.includes(marker)) {
    docOk = false;
    details.push(`page ${startPage} should start "${name}"`);
  }
}
check("documents: start on the declared pages (requirement order)", docOk, details.join("; "));

// original page order inside a document (each sample page prints "Page i of n")
let innerOk = true;
for (const [name, startPage, marker] of expectedDocPages) {
  const seen: string[] = [];
  for (let p = startPage - 1; p < totalPages; p++) {
    const text = pageTexts[p] ?? "";
    if (!text.includes(marker)) break;
    const m = /Page (\d+) of (\d+)/.exec(text.replace(/\s+/g, " "));
    if (m) seen.push(`${m[1]}/${m[2]}`);
  }
  if (seen.length > 0 && seen[0] !== `1/${seen[0].split("/")[1]}`) innerOk = false;
  if (seen.length > 1) {
    for (let i = 1; i < seen.length; i++) {
      const prev = Number(seen[i - 1].split("/")[0]);
      const cur = Number(seen[i].split("/")[0]);
      if (cur !== prev + 1) innerOk = false;
    }
  }
}
check("documents: original page order preserved", innerOk);

check("total page count matches expectation", totalPages === 24, `got ${totalPages}`);

/* ------------------------------------------------------------ report */

console.log(`\nVerification report - ${fileName} (${totalPages} pages)\n`);
let failed = 0;
for (const c of checks) {
  if (!c.pass) failed += 1;
  console.log(`  ${c.pass ? "✔" : "✘"} ${c.name}${c.detail ? ` — ${c.detail}` : ""}`);
}
console.log(
  `\n${failed === 0 ? "All checks passed." : `${failed} check(s) FAILED.`}\n`
);
process.exit(failed === 0 ? 0 : 1);

